//! Effective daemon defaults of the pinned Ceph option schema (spec ops-observability 6.6): `config show` and
//! `config get` answer every schema option, not only the ones this daemon interprets. The data table
//! `data/ceph-config-defaults.txt` (generated by `scripts/gen-ceph-config-defaults.sh` from the pinned schema) carries
//! the raw default; values are formatted per option type ([`crate::optval`]) and meta-expanded at the point of the
//! answer.
use crate::config::{ConfigDb, Level};
use crate::optval;
use std::collections::BTreeMap;

/// Data table: `name TAB value text`, `#` header lines first.
const DEFAULTS: &str = include_str!("../data/ceph-config-defaults.txt");

fn table() -> &'static BTreeMap<&'static str, &'static str> {
    static T: std::sync::OnceLock<BTreeMap<&'static str, &'static str>> =
        std::sync::OnceLock::new();
    T.get_or_init(|| {
        DEFAULTS
            .lines()
            .filter(|l| !l.starts_with('#'))
            .filter_map(|l| l.split_once('\t'))
            .collect()
    })
}

/// Type-normalized defaults, built from [`table`] once: `config get` must not format 2225 options per call.
fn effective() -> &'static BTreeMap<&'static str, String> {
    static E: std::sync::OnceLock<BTreeMap<&'static str, String>> = std::sync::OnceLock::new();
    E.get_or_init(|| {
        table()
            .iter()
            .map(|(k, v)| {
                (
                    *k,
                    optval::normalize(k, v).unwrap_or_else(|_| (*v).to_owned()),
                )
            })
            .collect()
    })
}

/// Every schema option name.
pub fn names() -> impl Iterator<Item = &'static str> {
    table().keys().copied()
}

/// The default of `name` as classic prints it (type-normalized, not meta-expanded), `None` for a non-schema name.
pub fn effective_default(name: &str) -> Option<&'static str> {
    effective().get(name).map(String::as_str)
}

/// What meta expansion needs about this daemon.
#[derive(Clone, Debug)]
pub struct Meta {
    pub cluster: String,
    /// `osd.<id>`
    pub name: String,
    pub ty: &'static str,
    pub id: String,
    pub host: String,
    pub pid: String,
}

impl Meta {
    pub fn new(cluster: &str, id: i32, host: &str) -> Meta {
        Meta {
            cluster: cluster.to_owned(),
            name: format!("osd.{id}"),
            ty: "osd",
            id: id.to_string(),
            host: host.to_owned(),
            pid: std::process::id().to_string(),
        }
    }

    /// `$cluster`, `$name`, `$type`, `$id`, `$host`, `$pid`, `$run_dir`, `$tmp_dir` (the two directories resolved from
    /// the effective config by [`show`]), also as `${..}`: the single-pass engine of [`osddir::expand_vars`], the same
    /// one the tools expand an OSD path with, so a value such as `admin_socket` means one path on both sides.
    pub fn expand(&self, v: &str, run_dir: &str, tmp_dir: &str) -> String {
        osddir::expand_vars(
            v,
            &[
                ("cluster", self.cluster.as_str()),
                ("name", self.name.as_str()),
                ("type", self.ty),
                ("id", self.id.as_str()),
                ("host", self.host.as_str()),
                ("pid", self.pid.as_str()),
                ("run_dir", run_dir),
                ("tmp_dir", tmp_dir),
            ],
        )
    }
}

/// `config show`: every schema option's effective value, meta-expanded, plus `name` and `cluster`.
pub fn show(conf: &ConfigDb, meta: &Meta) -> BTreeMap<String, String> {
    let mut m: BTreeMap<String, String> = effective()
        .iter()
        .map(|(k, v)| ((*k).to_owned(), v.clone()))
        .collect();
    for (k, v) in conf.all() {
        m.insert(k, v);
    }
    // the directories other meta variables refer to come from the effective values themselves
    let dirs = |k: &str| m.get(k).cloned().unwrap_or_default();
    let (run_dir, tmp_dir) = (dirs("run_dir"), dirs("tmp_dir"));
    for v in m.values_mut() {
        *v = meta.expand(v, &run_dir, &tmp_dir);
    }
    m.insert("name".into(), meta.name.clone());
    m.insert("cluster".into(), meta.cluster.clone());
    m
}

/// One effective value (override or schema default), not meta-expanded.
fn raw(conf: &ConfigDb, name: &str) -> Option<String> {
    match conf.get(name) {
        Some(v) => Some(v.to_owned()),
        None => effective_default(name).map(str::to_owned),
    }
}

/// The effective value of `name` as stored (override or schema default), not meta-expanded.
pub fn current(conf: &ConfigDb, name: &str) -> Option<String> {
    raw(conf, name)
}

/// One effective value with `$run_dir`/`$tmp_dir` available to the expansion.
fn value(conf: &ConfigDb, meta: &Meta, name: &str) -> Option<String> {
    let v = raw(conf, name)?;
    let run_dir = raw(conf, "run_dir").unwrap_or_default();
    let tmp_dir = raw(conf, "tmp_dir").unwrap_or_default();
    Some(meta.expand(&v, &run_dir, &tmp_dir))
}

/// `config get <name>`: the effective value of a schema option (or a stored non-schema key), meta-expanded.
pub fn get(conf: &ConfigDb, meta: &Meta, name: &str) -> Option<String> {
    value(conf, meta, name)
}

/// Dump a normalized option value with the schema's JSON type. Non-schema options retain their text.
fn dump_value(name: &str, text: &str) -> serde_json::Value {
    use optval::Kind;
    use serde_json::Value;
    let parsed = match optval::schema(name).map(|s| s.kind) {
        Some(Kind::Bool) => text.parse::<bool>().ok().map(Value::Bool),
        Some(Kind::Int) => text.parse::<i64>().ok().map(Value::from),
        Some(Kind::Uint) => text.parse::<u64>().ok().map(Value::from),
        Some(Kind::Float) => text
            .parse::<f64>()
            .ok()
            .and_then(serde_json::Number::from_f64)
            .map(Value::Number),
        _ => None,
    };
    parsed.unwrap_or_else(|| Value::String(text.to_owned()))
}

/// The options with a setting (classic: a non-empty source map), each with its settings per level number: a value at
/// any level above default, or a daemon default (level 0) that differs from the schema default (classic
/// `set_val_default`). A level-0 value equal to the schema default, or of an option without a schema default, is the
/// built-in default itself, not a setting. Feeds `config diff` and the mgr's `config_bl`.
pub fn configured(conf: &ConfigDb) -> impl Iterator<Item = (&String, &BTreeMap<u8, String>)> {
    conf.layers().filter(|(name, layers)| {
        layers.iter().any(|(level, text)| {
            *level != Level::Default as u8
                || effective_default(name).is_some_and(|d| d != text.as_str())
        })
    })
}

/// `config diff` (classic `md_config_t::diff`): every option with a setting at any source level, each level by its
/// classic name (`default`, `mon`, `file`, `env`, `cmdline`, `override`) plus `final`, typed per option. An explicit
/// value equal to the default still appears: the command reports sources, not inequality. The `default` entry is the
/// daemon's own default where it sets one (a level-0 value that differs from the schema default, classic
/// `set_val_default`), else the schema default. `cluster` is the daemon's identity, not an option (classic omits it).
pub fn diff(conf: &ConfigDb, meta: &Meta) -> BTreeMap<String, BTreeMap<String, serde_json::Value>> {
    configured(conf)
        .filter(|(name, _)| name.as_str() != "cluster")
        .map(|(name, layers)| {
            let mut entry = BTreeMap::new();
            if let Some(default) = effective_default(name) {
                entry.insert("default", dump_value(name, default));
            }
            for (level, text) in layers {
                if let Some(source) = Level::name(*level) {
                    entry.insert(source, dump_value(name, text));
                }
            }
            if let Some(final_value) = value(conf, meta, name) {
                entry.insert("final", dump_value(name, &final_value));
            }
            (
                name.clone(),
                entry.into_iter().map(|(k, v)| (k.to_owned(), v)).collect(),
            )
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn meta() -> Meta {
        Meta::new("ceph", 3, "node1")
    }

    #[test]
    fn the_table_covers_the_option_schema() {
        assert_eq!(table().len(), 2225);
        for name in optval::names() {
            assert!(table().contains_key(name), "no default for {name}");
        }
        // every default is a value the option type accepts (an empty default is the type-zero of an unset option)
        for (name, raw) in table() {
            assert!(
                raw.is_empty() || optval::normalize(name, raw).is_ok(),
                "{name} default {raw:?} is not a valid value"
            );
        }
    }

    #[test]
    fn meta_expansion_is_single_pass_and_brace_aware() {
        let m = meta();
        assert_eq!(
            m.expand("/x/${cluster}/$name", "/run", "/tmp"),
            "/x/ceph/osd.3"
        );
        assert_eq!(m.expand("$unknown/$", "/run", "/tmp"), "$unknown/$");
        // a substituted value is not expanded again (a cluster named `$id` stays `$id`)
        let mut m = meta();
        m.cluster = "$id".into();
        assert_eq!(m.expand("$cluster", "/run", "/tmp"), "$id");
    }

    /// Config diff preserves provenance even when an explicit value equals its default.
    #[test]
    fn config_diff_reports_typed_layers_and_final_even_for_equal_values() {
        use crate::config::Level;
        use serde_json::json;
        let mut conf = ConfigDb::default();
        conf.set(Level::Mon, "log_max_recent", "42").unwrap();
        conf.set(Level::File, "log_max_recent", "10000").unwrap();
        conf.set(Level::Override, "log_max_recent", "10000")
            .unwrap();
        conf.set(Level::Override, "log_to_stderr", "false").unwrap();
        conf.set(Level::Override, "osd_op_complaint_time", "1.25")
            .unwrap();
        conf.set(Level::Override, "bdev_block_size", "8K").unwrap();
        conf.set(Level::Override, "log_file", "$run_dir/$name.log")
            .unwrap();
        // every startup source keeps its classic name
        conf.set(Level::File, "osd_max_backfills", "2").unwrap();
        conf.set(Level::Env, "osd_max_backfills", "3").unwrap();
        conf.set(Level::Cmdline, "osd_max_backfills", "4").unwrap();
        // a daemon default that differs from the schema default is a setting (classic `set_val_default`) and replaces the
        // schema default; the core's defaults equal to the schema default and `cluster` are not
        conf.set_default_unchecked("osd_objectstore", "flashstore");
        conf.set(Level::Cmdline, "cluster", "ceph").unwrap();
        let d = serde_json::to_value(diff(&conf, &meta())).unwrap();
        assert_eq!(
            d["osd_max_backfills"],
            json!({"default": 1, "file": 2, "env": 3, "cmdline": 4, "final": 4})
        );
        assert_eq!(
            d["osd_objectstore"],
            json!({"default": "flashstore", "final": "flashstore"})
        );
        assert!(d.get("cluster").is_none());
        let mut cfg = configured(&conf).map(|(k, _)| k.as_str());
        assert!(cfg.any(|k| k == "osd_objectstore"));
        assert_eq!(
            d["log_max_recent"],
            json!({"default": 10000, "mon": 42, "file": 10000,
                "override": 10000, "final": 10000})
        );
        assert_eq!(
            d["log_to_stderr"],
            json!({"default": true, "override": false, "final": false})
        );
        assert_eq!(
            d["osd_op_complaint_time"],
            json!({"default": 30.0, "override": 1.25, "final": 1.25})
        );
        assert_eq!(d["bdev_block_size"]["override"], "8192");
        assert_eq!(d["bdev_block_size"]["final"], "8192");
        assert_eq!(d["log_file"]["override"], "$run_dir/$name.log");
        assert_eq!(d["log_file"]["final"], "/var/run/ceph/osd.3.log");
        assert!(d.get("osd_heartbeat_grace").is_none());
    }

    #[test]
    fn daemon_defaults_win_and_values_are_formatted_and_expanded() {
        let conf = ConfigDb::default();
        let m = show(&conf, &meta());
        assert_eq!(m["log_file"], "/var/log/ceph/ceph-osd.3.log");
        assert_eq!(m["admin_socket"], "/var/run/ceph/ceph-osd.3.asok");
        assert_eq!(m["log_max_recent"], "10000");
        assert_eq!(m["log_to_stderr"], "true");
        assert_eq!(m["log_to_file"], "false");
        assert_eq!(m["osd_op_complaint_time"], "30.000000");
        assert_eq!(m["pid_file"], "");
        assert_eq!(m["name"], "osd.3");
        assert_eq!(m["cluster"], "ceph");
        // the keyring default lists the three search paths, $cluster and $name expanded
        assert_eq!(
            m["keyring"],
            "/etc/ceph/ceph.osd.3.keyring,/etc/ceph/ceph.keyring,/etc/ceph/keyring,/etc/ceph/keyring.bin"
        );
        // an override wins over the default
        let mut conf = conf;
        conf.set(crate::config::Level::Override, "log_max_recent", "42")
            .unwrap();
        assert_eq!(get(&conf, &meta(), "log_max_recent").as_deref(), Some("42"));
        assert_eq!(
            get(&conf, &meta(), "log_file").as_deref(),
            Some("/var/log/ceph/ceph-osd.3.log")
        );
        assert_eq!(get(&conf, &meta(), "no_such_option"), None);
        let d = diff(&conf, &meta());
        let entry = d.get("log_max_recent").expect("explicit override");
        assert_eq!(entry["default"], serde_json::json!(10000));
        assert_eq!(entry["override"], serde_json::json!(42));
        assert_eq!(entry["final"], serde_json::json!(42));
        // the core's built-in defaults equal to the schema default are no settings
        assert!(
            !d.contains_key("osd_op_complaint_time"),
            "unchanged defaults are not diffed"
        );
    }
}
